<div class="dash-wrap"><div class="dash-head"><div><div class="dash-greeting">Store</div><h1 class="dash-name">Place an Order</h1><div class="dash-date">Select products and submit your delivery details</div></div></div><div class="row g-4"><div class="col-lg-8"><div class="row g-3">@forelse($products as $product)<div class="col-md-6 col-xl-4"><div class="dash-card h-100"><div class="dash-card-top"><span class="dash-card-title">{{ $product->category->name ?? 'Product' }}</span><span class="dash-card-icon"><i class="fas fa-box"></i></span></div><h3 class="h6 mt-3">{{ $product->name }}</h3><p class="text-muted small">{{ $product->description ?: 'Available for order' }}</p><div class="fw-bold mb-3" data-price="{{ $product->id }}">Select quantity</div><input type="number" min="0" value="0" class="form-control order-qty" data-id="{{ $product->id }}" data-name="{{ $product->name }}"></div></div>@empty<div class="col-12"><div class="empty-box">No products are currently available.</div></div>@endforelse</div></div><div class="col-lg-4"><div class="dash-panel sticky-lg-top" style="top:80px"><div class="dash-panel-head">Checkout</div><div class="dash-panel-body"><form id="orderForm">@csrf<input name="customer_name" class="form-control mb-2" placeholder="Full name" required><input name="phone" class="form-control mb-2" placeholder="Phone number" required><input name="email" type="email" class="form-control mb-2" placeholder="Email (optional)"><textarea name="delivery_location" class="form-control mb-2" placeholder="Delivery location" required></textarea><select name="branch_id" class="form-select mb-2" required><option value="">Select branch</option>@foreach($branches as $branch)<option value="{{ $branch->id }}">{{ $branch->name }}</option>@endforeach</select><select name="payment_method" class="form-select mb-3" required><option value="">Payment method</option><option value="mobile-money">Mobile Money</option><option value="cash-on-delivery">Cash on delivery</option></select><button class="btn btn-primary w-100" data-bs-toggle="modal" data-bs-target="#orderResult"><i class="fas fa-check"></i> Submit Order</button></form></div></div></div></div></div><div class="modal fade" id="orderResult" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Order submitted</h5></div><div class="modal-body" id="orderResultBody">Submitting...</div><div class="modal-footer"><a href="{{ route('place-order') }}" class="btn btn-primary">Place another order</a></div></div></div></div>
@push('scripts')<script>document.getElementById('orderForm')?.addEventListener('submit',async e=>{e.preventDefault();const items=[...document.querySelectorAll('.order-qty')].filter(x=>+x.value>0).map(x=>({id:x.dataset.id,quantity:+x.value}));const form=e.currentTarget;const body=new FormData(form);body.append('items',JSON.stringify(items));const r=await fetch('{{ route('place-order.store') }}',{method:'POST',headers:{'Accept':'application/json'},body});const d=await r.json();document.getElementById('orderResultBody').textContent=d.success?'Thank you. Your order number is '+d.order_number+'.':(d.message||'Please check the form and try again.');if(d.success) form.reset();});</script>@endpush
